export function summarize(readings) {
  if (_.isEmpty(readings)) throw new Error('no readings');
  const values = _.map(readings, 'value');
  const sorted = _.sortBy(values);
  const n = values.length;
  const mid = Math.floor(n / 2);
  const median = n % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
  return {
    n,
    mean: _.round(math.mean(values), 3),
    sd: _.round(n > 1 ? math.std(values) : 0, 3),
    median: _.round(median, 3),
    min: _.min(values),
    max: _.max(values),
    start: moment(_.first(readings).ts).format('YYYY-MM-DD HH:mm'),
  };
}
