// summary.js
const pad = (n) => String(n).padStart(2, '0');

// same rounding as lodash _.round
function round(x, digits) {
  if (!Number.isFinite(x)) return x;
  const [m, e = 0] = String(x).split('e');
  const r = Math.round(`${m}e${+e + digits}`);
  const [m2, e2 = 0] = String(r).split('e');
  return +`${m2}e${+e2 - digits}`;
}

function formatStart(ts) {
  const d = new Date(ts);
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

export function summarize(readings) {
  if (!readings || !readings.length) throw new Error('no readings');
  const values = readings.map((r) => r.value);
  const n = values.length;
  const mean = values.reduce((a, b) => a + b, 0) / n;
  const sd = n > 1
    ? Math.sqrt(values.reduce((a, v) => a + (v - mean) ** 2, 0) / (n - 1))
    : 0;
  const sorted = [...values].sort((a, b) => a - b);
  const mid = n >> 1;
  const median = n % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
  return {
    n,
    mean: round(mean, 3),
    sd: round(sd, 3),
    median: round(median, 3),
    min: sorted[0],
    max: sorted[n - 1],
    start: formatStart(readings[0].ts),
  };
}
