    mean = total / len(values)

    lo = values[0]
    hi = values[0]
    for v in values:
        if v < lo:
            lo = v
        if v > hi:
            hi = v

    sq = 0.0
    for v in values:
        sq += (v - mean) ** 2
    std = math.sqrt(sq / len(values))
    return mean, lo, hi, std


def calibrate(values, gain, offset):
    out = []
    for i in range(len(values)):
        out.append(values[i] * gain + offset)
    return out


def count_over(values, limit):
    n = 0
    for v in values:
        if v > limit:
