  if (!f.endsWith('.log')) continue;
  const full = path.join(LOG_DIR, f);
  const data = fs.readFileSync(full);
  const start = offsets[f] || 0;
  if (data.length <= start) continue;
  ship(f, data.subarray(start));
  offsets[f] = data.length;
}
fs.writeFileSync(STATE, JSON.stringify(offsets));
