**Workload:** script (cron job on every app server, runs every minute)

#### [Bug] Offset is saved even when the upload fails
- **Where:** `offsets[f] = data.length` and the `req.on('error')` handler
- **Issue:** `ship()` is fire-and-forget. A network error or a 5xx response is only logged or ignored, but the offset has already moved on. Those log lines are never sent again. Also, if a log file is rotated and becomes smaller than the saved offset, `data.length <= start` stays true and nothing is shipped until the file grows past the old offset.
- **Fix:** wait for the response, and save the offset only after a 2xx. If the file is smaller than the saved offset, start from 0.

#### [High] Brotli quality 11 on data that is used once
- **Where:** `ship()`, `BROTLI_PARAM_QUALITY: 11`
- **Issue:** every minute, on every server, fresh log data is compressed at the slowest brotli setting. The collector reads it once. Quality 11 is meant for static assets that are compressed once and served many times.
- **Fix:** use a low quality such as 4. This keeps `Content-Encoding: br`, so the collector needs no change. If the collector also accepts gzip, `zlib.gzip` at the default level is another cheap choice.
- **Impact:** reduces E on every server, every minute. In Green Metrics Tool micro-benchmarks on 100 MB of English text with CLI default settings, brotli (quality 11) used about 3019 J and gzip about 67 J, about 45× more for brotli ([measurements](https://metrics.green-coding.io/compare-simple.html?ids=fb08d3c3-ba41-4f0f-85fd-0b6c34e6c39b,f1479db0-c453-4aaa-9116-e137621fad07,8e93a8d2-60b0-4831-905b-764b68257bc7)). That compares energy only, not file size. Higher quality gives somewhat smaller uploads, but on an internal link that rarely repays the CPU cost.
- **Pattern:** https://patterns.greensoftware.foundation/development/data-handling/compress-transmitted-data

#### [Medium] Whole file is read and compressed synchronously
- **Where:** `fs.readFileSync(full)` and `brotliCompressSync`
- **Issue:** the full log file is loaded into memory on every run, only to send the tail. Large logs mean a lot of wasted I/O and memory each minute. The sync compression also blocks the event loop.
- **Fix:** open the file, read only the bytes after the saved offset, and use async `brotliCompress`.

Here is the script with all three changes:

```javascript
#!/usr/bin/env node
const fs = require('fs');
const zlib = require('zlib');
const https = require('https');
const path = require('path');
const { promisify } = require('util');

const brotli = promisify(zlib.brotliCompress);

const LOG_DIR = process.argv[2] || '/var/log/myapp';
const STATE = '/tmp/ship-logs.offset.json';
const ENDPOINT = new URL(process.env.COLLECTOR_URL || 'https://logs.internal.example/ingest');

function loadOffsets() {
  try { return JSON.parse(fs.readFileSync(STATE, 'utf8')); } catch (e) { return {}; }
}

async function readFrom(full, start) {
  const fh = await fs.promises.open(full, 'r');
  try {
    const { size } = await fh.stat();
    const from = size < start ? 0 : start; // file was rotated
    if (size <= from) return { chunk: null, size };
    const chunk = Buffer.alloc(size - from);
    await fh.read(chunk, 0, chunk.length, from);
    return { chunk, size };
  } finally {
    await fh.close();
  }
}

async function ship(name, chunk) {
  const body = await brotli(chunk, {
    params: { [zlib.constants.BROTLI_PARAM_QUALITY]: 4 },
  });
  return new Promise((resolve, reject) => {
    const req = https.request(ENDPOINT, {
      method: 'POST',
      headers: {
        'Content-Type': 'text/plain',
        'Content-Encoding': 'br',
        'X-Log-Name': name,
        'Content-Length': body.length,
      },
    }, res => {
      res.resume();
      res.on('end', () =>
        res.statusCode < 300 ? resolve() : reject(new Error(`HTTP ${res.statusCode}`)));
    });
    req.on('error', reject);
    req.end(body);
  });
}

async function main() {
  const offsets = loadOffsets();
  for (const f of fs.readdirSync(LOG_DIR)) {
    if (!f.endsWith('.log')) continue;
    try {
      const { chunk, size } = await readFrom(path.join(LOG_DIR, f), offsets[f] || 0);
      if (!chunk) { offsets[f] = size; continue; }
      await ship(f, chunk);
      offsets[f] = size; // only after a successful upload
    } catch (err) {
      console.error(`${f}: ${err.message}`);
    }
  }
  fs.writeFileSync(STATE, JSON.stringify(offsets));
}

main();
```

**Already good:** only new bytes are sent, not the whole file again, and the payload is compressed before upload.

I wrote a small CLI that summarizes our nginx access logs (combined format). We run it from cron on the log server against the daily file, which is usually 5-10 GB, so a few tens of millions of lines. Many request paths carry query strings, so there are a lot of distinct paths.

Requirements: it must keep working with the same output format, because another script parses it. It must not crash on broken lines. It should stay stdlib only. Could you review it for correctness and efficiency?

```python
#!/usr/bin/env python3
"""logsum: summarize an nginx access log (combined format)."""
import argparse
import sys


def summarize(lines):
    hits = {}
    sizes = {}
    classes = {}
    bad = 0
    for line in lines:
        parts = line.split()
        try:
            path = parts[6]
            status = int(parts[8])
            size = int(parts[9])
        except (IndexError, ValueError):
            bad += 1
            continue
        try:
            hits[path] += 1
            sizes[path] += size
        except KeyError:
            hits[path] = 1
            sizes[path] = size
        key = status // 100
        try:
            classes[key] += 1
        except KeyError:
            classes[key] = 1
    return hits, sizes, classes, bad


def main():
    ap = argparse.ArgumentParser(description="Summarize an access log")
    ap.add_argument("logfile")
    ap.add_argument("--top", type=int, default=10)
    args = ap.parse_args()

    with open(args.logfile) as f:
        lines = f.readlines()

    hits, sizes, classes, bad = summarize(lines)

    ranked = sorted(hits.items(), key=lambda kv: kv[1], reverse=True)
    for path, n in ranked[:args.top]:
        print(f"{n:8d} {sizes[path]:12d} {path}")
    for key in sorted(classes):
        print(f"{key}xx: {classes[key]}")
    print(f"skipped: {bad}")


if __name__ == "__main__":
    main()
```

